Describe 'Test-MtGsaCompliantNetworkBreakGlassExcluded' {
    Context 'When no emergency access accounts are configured' {
        It 'Skips the test instead of letting it be counted as passed' {
            # The check states that break-glass exclusion cannot be verified and returns
            # $null. The bundled MT.1191 wrapper only asserts when the result is non-null,
            # so without a skip reason the It block completes with no assertion at all and
            # Pester reports Passed. Add-MtTestResultDetail calls Set-ItResult -Skipped only
            # when -SkippedBecause is supplied, which is what keeps an unverifiable control
            # out of the passed count.
            InModuleScope Maester {
                Mock Test-MtConnection { $true }
                Mock Get-MtLicenseInformation { 'P1' }
                Mock Get-MtCompliantNetworkPolicy {
                    @([pscustomobject]@{ displayName = 'Compliant Network'; id = 'policy-01' })
                }
                Mock Get-MtEmergencyAccessAccount { @() }
                Mock Add-MtTestResultDetail { }

                $result = Test-MtGsaCompliantNetworkBreakGlassExcluded

                $result | Should -BeNullOrEmpty
                Should -Invoke Add-MtTestResultDetail -Times 1 -Exactly -ParameterFilter {
                    $SkippedBecause -eq 'Custom' -and $SkippedCustomReason -like '*cannot be verified*'
                }
            }
        }
    }

    Context 'When emergency access accounts are configured' {
        It 'Returns false when a policy does not exclude a break-glass account' {
            InModuleScope Maester {
                Mock Test-MtConnection { $true }
                Mock Get-MtLicenseInformation { 'P1' }
                Mock Get-MtCompliantNetworkPolicy {
                    @([pscustomobject]@{
                            displayName = 'Compliant Network'
                            id          = 'policy-01'
                            conditions  = @{ users = @{ excludeUsers = @(); excludeGroups = @() } }
                        })
                }
                Mock Get-MtEmergencyAccessAccount {
                    @([pscustomobject]@{ ObjectId = 'bg-user-01'; DisplayName = 'Break Glass 01'; Type = 'user' })
                }
                Mock Invoke-MtGraphRequest { @() }
                Mock Add-MtTestResultDetail { }

                Test-MtGsaCompliantNetworkBreakGlassExcluded | Should -BeFalse
            }
        }

        It 'Returns true when the break-glass account is excluded' {
            InModuleScope Maester {
                Mock Test-MtConnection { $true }
                Mock Get-MtLicenseInformation { 'P1' }
                Mock Get-MtCompliantNetworkPolicy {
                    @([pscustomobject]@{
                            displayName = 'Compliant Network'
                            id          = 'policy-01'
                            conditions  = @{ users = @{ excludeUsers = @('bg-user-01'); excludeGroups = @() } }
                        })
                }
                Mock Get-MtEmergencyAccessAccount {
                    @([pscustomobject]@{ ObjectId = 'bg-user-01'; DisplayName = 'Break Glass 01'; Type = 'user' })
                }
                Mock Invoke-MtGraphRequest { @() }
                Mock Add-MtTestResultDetail { }

                Test-MtGsaCompliantNetworkBreakGlassExcluded | Should -BeTrue
            }
        }
    }
}
﻿param (
    $TestGeneral = $true,

    $TestFunctions = $true,

    [ValidateSet('None', 'Normal', 'Detailed', 'Diagnostic')]
    [Alias('Show')]
    $Output = "None",

    # File name patterns to run, for example 'Get-MtUser*' or 'RepositoryLayout*', 'Help*'.
    [string[]]
    $Include = "*",

    # File name patterns to skip, for example 'Golden*', 'GeneratedFileFormatting*'.
    [string[]]
    $Exclude = "",

    [switch]
    $NoError,

    # When set (or when $env:PESTER_COVERAGE equals 'true'), runs all tests in a single combined Pester invocation and generates a JaCoCo code-coverage report.
    [switch]
    $Coverage,

    # How many pwsh processes run test files at the same time. The default is 2 (1 on a single-core machine):
    # each process needs up to about 1.3 GB of memory, and 4 at once peaked at about 4.4 GB. On a machine with
    # memory to spare, -ThrottleLimit 4 runs the suite in about half the time.
    [ValidateRange(1, 64)]
    [int]
    $ThrottleLimit = [Math]::Min(2, [Environment]::ProcessorCount),

    # How many test files each pwsh process runs before it exits and frees its memory.
    [ValidateRange(1, 1000)]
    [int]
    $FilesPerProcess = 8,

    # Runs every test file in this process, as pester.ps1 used to. Useful when debugging a test,
    # but each file that re-imports the module keeps another copy of it in memory (about 60 MB each).
    [switch]
    $InProcess,

    # When set (or when $env:PESTER_SKIP_OS_INDEPENDENT equals 'true'), skips the tests whose result does not depend
    # on the operating system: the general tests that only read files (lint, formatting, ScriptAnalyzer, help,
    # generator drift) and the golden fixtures. CI runs them on the Linux leg only.
    [switch]
    $SkipOsIndependent,

    # When set (or when $env:PESTER_SKIP_GOLDEN equals 'true'), skips the Maester 2.x golden fixtures. CI sets it on
    # a pull request that changes none of their inputs.
    [switch]
    $SkipGolden
)

